python3 -c 'import math
P={(r,c) for r in range(5) for c in range(5) if r in (0,4) or c in (0,4)}
Q={(0,0),(0,1),(0,2),(1,3),(2,0),(2,4),(3,1),(3,5),(4,2),(4,3),(4,4),(4,5),(4,6)}
# brute nearest-cell affine rotation + independent scale, centered at source center; compare best target overlap, allowing translation
best=[]
for deg in range(-180,181):
 a=math.radians(deg)
 for sx in [i/20 for i in range(5,41)]:
  for sy in [i/20 for i in range(5,41)]:
   co,si=math.cos(a),math.sin(a)
   coords=[]
   for r,c in P:
    x=c-2;y=r-2
    xx=sx*co*x-sy*si*y; yy=sx*si*x+sy*co*y
    coords.append((yy,xx))
   # translation candidates align output bbox to target bbox with integer offset
   for tr in range(-2,6):
    for tc in range(-2,8):
     S={(round(y+tr),round(x+tc)) for y,x in coords}
     score=len(S&Q)-len(S-Q)-len(Q-S)
     best.append((score,deg,sx,sy,tr,tc,len(S&Q),len(S)))
best.sort(reverse=True)
print(best[:10])'

python3 -c 'rows={3:[6,7,8],4:[4,5,6,8],5:[4,8],6:[4,5,8],7:[5,8,9],8:[5,9],9:[5,6,7,8,9]}; H,W=11,13; bottom=max(rows); out=[[0]*W for _ in range(H)]; mapped={};
for r,cs in rows.items():
 shift=bottom-r
 mapped[r]=[]
 for c in cs:
  nc=c-shift
  if 0<=nc<W: out[r][nc]=7; mapped[r].append(nc)
print("mapped:",mapped)
print("counts:",[sum(row) for row in out])
print("grid:")
for row in out: print(" ".join(map(str,row)))
assert all(len(row)==W for row in out)'
